import './../styles/article.css'
import {articleList} from '../datas/articleList.js'


function Article() {
    return (
        <div>
            {articleList.map((article) => (
                <div className="card">
                    <img src={article.image} alt="Planche Jaune" className="card-image"/>
                    <p>{article.prix}€</p>
                    <p>{article.nom}</p>
                </div>
            ))}
        </div>
    
    )
}
export default Article;
